#include <WiFi.h>

void setup()
 {
  Serial.begin(115200);
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
  delay(100);
  Serial.println("Wi-Fi scan started");
}


void ask()
  {
  if (Serial.available())
    {
    auto a = Serial.read();
    Serial.write(a);

    if (a>='1' && a<='4') 
      {
      Serial.printf( "Command:" );
      }
    }
  }

void wfScan()
  {
  int count = WiFi.scanNetworks();
  Serial.printf("Found %d network(s)\n", count);

  for (int i = 0; i < count; i++) {
    Serial.printf("%2d: %s (%d dBm)%s\n",
      i + 1,
      WiFi.SSID(i).c_str(),
      WiFi.RSSI(i),
      WiFi.encryptionType(i) == WIFI_AUTH_OPEN ? " open" : "");
  }

  WiFi.scanDelete();
  }

void loop()
  {
  delay(5000);
  }
